 53| static void strstriplt(char *buf)
 54| {
 55|     size_t len;
 56|     int a;
 57| 
 58|     if (buf == NULL) {
 59|         return;
 60|     }
 61|     if (buf[0] == 0) {
 62|         return;
 63|     }
 64|     len = strlen(buf);
 65|     /* the casts to unsigned char below are to work around isspace asserts
 66|        on Windows due to non-ascii characters becoming negative */
 67|     while ((buf[0] != 0) && (isspace((unsigned char)buf[len - 1]))) {
 68|         buf[--len] = 0;
 69|     }
 70|     if (buf[0] == 0) {
 71|         return;
 72|     }
 73|     a = 0;
 74|     while ((buf[0] != 0) && (isspace((unsigned char)buf[a]))) {
 75|         a++;
 76|     }
 77|     if (a > 0) {
 78|         memmove(buf, &buf[a], len - a + 1);
 79|     }
