1311| char *icalparser_string_line_generator(char *out, size_t buf_size, void *d)
1312| {
1313|     int replace_cr = 0;
1314|     char *n;
1315|     size_t size;
1316|     struct slg_data *data = (struct slg_data *)d;
1317| 
1318|     if (data->pos == 0) {
1319|         data->pos = data->str;
1320| 
1321|         /* Skip the UTF-8 marker at the beginning of the string */
1322|         if (((unsigned char)data->pos[0]) == 0xEF &&
1323|             ((unsigned char)data->pos[1]) == 0xBB &&
1324|             ((unsigned char)data->pos[2]) == 0xBF) {
1325|             data->pos += 3;
1326|         }
1327|     }
1328| 
1329|     /* If the pointer is at the end of the string, we are done */
1330|     if (*(data->pos) == 0) {
1331|         return 0;
1332|     }
1333| 
1334|     n = strchr(data->pos, '\n');
1335| 
1336|     if (n == 0) {
1337|         n = strchr(data->pos, '\r'); /* support malformed input with only CR and no LF
1338|                                         (e.g. from Kerio Connect Server) */
1339|         if (n == 0) {
1340|             size = strlen(data->pos);
1341|         } else {
1342|             n++; /* include CR in output - will be replaced by LF later on */
1343|             replace_cr = 1;
1344|             size = (size_t)(ptrdiff_t)(n - data->pos);
1345|         }
1346|     } else {
1347|         n++; /* include newline in output */
1348|         size = (size_t)(ptrdiff_t)(n - data->pos);
1349|     }
1350| 
1351|     if (size > buf_size - 1) {
1352|         size = buf_size - 1;
1353|     }
1354| 
1355| #if defined(__GNUC__) && !defined(__clang__)
1356| #pragma GCC diagnostic push
1357| #pragma GCC diagnostic ignored "-Wstringop-truncation"
1358| #pragma GCC diagnostic ignored "-Wstringop-overflow"
1359| #endif
1360|     strncpy(out, data->pos, size);
1361| #if defined(__GNUC__) && !defined(__clang__)
1362| #pragma GCC diagnostic pop
1363| #endif
1364| 
1365|     if (replace_cr) {
1366|         *(out + size - 1) = '\n';
1367|     }
1368|     *(out + size) = '\0';
1369| 
1370|     data->pos += size;
1371| 
1372|     return out;
1373| }
